import { Component, inject, Input } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { IconMap } from './ap-icon-map.type';
import { UTILITY_ICONS } from './utility-icons';

@Component({
  selector: 'ap-icon',
  imports: [],
  templateUrl: './ap-icon.component.html',
  styleUrl: './ap-icon.component.css'
})
export class ApIconComponent {
  @Input()
  set name(value: string) {
    this._name = value || '';
    this.svgHtml = this.getSvgHtml(this._name);
  }
  get name(): string {
    return this._name;
  }

  svgHtml: SafeHtml = '';
  private _name = '';

  private sanitizer = inject(DomSanitizer);
  private iconMap: IconMap = UTILITY_ICONS;

  private getSvgHtml(name: string): SafeHtml {
    if (!name) return '';

    const [iconName, style = 'default'] = name.split(' ');
    const iconSet = this.iconMap[iconName];
    const rawSvg = iconSet?.[style] || iconSet?.['default'] || '';

    const cleaned = this.removeSvgClass(rawSvg);
    return this.sanitizer.bypassSecurityTrustHtml(cleaned);
  }

  private removeSvgClass(svg: string): string {
    return svg.replace(/\s*class="[^"]*"/g, '');
  }
}
